import SwiftUI
struct SettingsScreen: View {
    @State private var notifications = false
    var body: some View {
        VStack {
            Text(notifications ? "Уведомления включены" : "Уведомления выключены")
            NotificationsSwitch(isEnabled: $notifications)
            Button("Выключить") { notifications = false }
        }
    }
}
struct NotificationsSwitch: View {
    @Binding var isEnabled: Bool
    var body: some View {
        Toggle("Уведомления", isOn: $isEnabled)
    }
}

import SwiftUI
struct CounterScreen: View {
    @State private var count = 2
    var body: some View {
        VStack {
            Text("Напоминаний: \(count)")
            Stepper("Количество", value: .constant(count), in: 1...5)
        }
    }
}

