import SwiftUI
struct CounterScreen: View {
    @State private var count = 2
    var body: some View {
        VStack {
            Text("Напоминаний: \(count)")
            Stepper("Количество", value: $count, in: 1...5)
        }
    }
}

.constant создаёт фиксированный Binding: он не меняет count. $count даёт доступ к состоянию владельца; последовательность после исправления — 2 → 3 → 4, а допустимые границы — 1 и 5.

