import SwiftUI
struct ProfileScreen: View {
    @State private var name = "Анна"
    var body: some View {
        VStack {
            NameLabel(name: name)
            NameEditor(name: $name)
        }
    }
}
struct NameLabel: View {
    let name: String
    var body: some View { Text(name) }
}
struct NameEditor: View {
    @Binding var name: String
    var body: some View { TextField("Имя", text: $name) }
}

NameLabel получает строку name для чтения. NameEditor получает $name для чтения и записи родительского состояния. Обычное let у NameLabel не замораживает надпись навсегда: при обновлении родитель передаст новое значение, и Text покажет «Мария».
